column3:
a: id(a) & {dependsOn: rel() & acyclic() & [b, c]}
b: id(b) & {dependsOn: rel() & acyclic() & [d]}
c: id(c) & {dependsOn: rel() & acyclic() & [d]}
d: id(d) & {}

@"std/system"

services: {
  auth: id(svc_auth) & $.std.Service & {}
  billing: id(svc_billing) & $.std.Service & {dependsOn: rel($.std.Service) & inverse(dependedOnBy) & acyclic() & [svc_auth]}
}

a: id(a) & {dependsOn: rel() & acyclic() & inverse(usedBy) & [b]}
b: id(b) & {dependsOn: rel() & acyclic() & inverse(usedBy) & [a]}
a: {dependsOn: rel()}
b: {usedBy: rel() & [a]}
a: {usedBy: rel() & [b]}
